import { Alert, Button } from 'react-native';

<Button
  title="Show Alert"
  onPress={() => {
    Alert.alert(
      'Alert Title',
      'My Alert Message',
      [
        { text: 'Cancel', onPress: () => console.log('Cancel Pressed'), style: 'cancel' },
        { text: 'OK', onPress: () => console.log('OK Pressed') }
      ],
      { cancelable: false }
    );
  }}
/>
